export const INVENTORY_WINDOWS_CSS = "\n.dialog-title{flex:1;display:flex;flex-direction:column;gap:2px;padding-top:2px}\n.dialog-title h3{padding-top:0}\n.inv-glyph{display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:12px;\n background:var(--mp-raised);color:var(--mp-violet-text);font-weight:800;font-size:20px}\n.inv-glyph[data-size=\"56\"]{width:56px;height:56px;font-size:26px}\n.inv-glyph[data-size=\"32\"]{width:32px;height:32px;font-size:16px}\n.inv-glyph[data-size=\"28\"]{width:28px;height:28px;font-size:14px}\n.dialog:has(.inv-grid),.dialog:has(.chest-list),.dialog:has(.chest-rewards){width:min(358px,100%)}\n.dialog:has(.inv-grid){overflow-x:hidden}.dialog:has(.inv-grid)>*{min-width:0}\n.inv-tabs{display:grid;grid-template-columns:1fr 1fr;gap:4px;padding:2px;border-radius:12px;\n background:var(--mp-window-background);border:1px solid var(--mp-line)}\n.dialog .inv-tabs button{height:44px;min-height:44px;padding:0 14px;border:0;border-radius:8px;background:transparent;\n color:var(--mp-text-2);font-size:15px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:6px}\n.dialog .inv-tabs button[aria-selected=\"true\"]{background:var(--mp-violet);color:var(--mp-on-accent)}\n.inv-count{height:20px;min-width:20px;padding:0 6px;box-sizing:border-box;border-radius:10px;\n background:var(--mp-window-background);color:var(--mp-violet-text);font-weight:700;font-size:12px;line-height:20px}\n.inv-grid{flex:0 1 auto;min-height:0;overflow-y:auto;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));\n grid-auto-rows:84px;gap:8px;align-content:start}\n.dialog .inv-cell{position:relative;min-width:0;min-height:0;height:auto;overflow:hidden;box-sizing:border-box;\n border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line);display:flex;flex-direction:column;\n align-items:center;justify-content:center;gap:4px;padding:4px 0;color:var(--mp-text);container-type:size}\n.dialog .inv-cell[aria-pressed=\"true\"]{background:var(--mp-raised);border:2px solid var(--mp-violet)}\n.dialog .inv-cell[data-empty]{background:var(--mp-night);border-style:dashed;opacity:.55}\n/* Art is 40px (MPS); a flex item, it shrinks (down to 16px) only when the cell is lower than the\n art and the name need: a 3-line name, a wide badge, a short landscape zone. */\n.inv-cell>img,.inv-cell>.inv-glyph{flex:0 1 40px;min-height:16px;width:auto;height:auto;aspect-ratio:1;\n object-fit:contain;font-size:clamp(10px,50cqh - 16px,20px)}\n.inv-name{flex:none;min-width:0;max-width:100%;font-weight:600;font-size:12px;line-height:14px;color:var(--mp-text-2);\n overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;line-clamp:3;\n text-align:center;overflow-wrap:break-word;hyphens:auto;hyphenate-limit-chars:10 4 4}\n/* A long name (a word over 9 letters or over 18 in all) takes 11px with tight tracking, so «Перемешать»\n fits the 66px cell of a 375px phone unhyphenated; the full name is also the cell's title. A cell\n narrower than the 71px of the board (a 360px phone) takes 11px with tighter tracking, so a word of\n 10 letters («Перемешать») stays whole. */\n.inv-cell[data-long-name] .inv-name{font-size:11px;line-height:13px;letter-spacing:-.03em}\n@container (max-width:66px){.dialog .inv-cell>.inv-name{font-size:11px;line-height:13px;letter-spacing:-.05em}.inv-cell>.inv-qty{padding:0 4px;font-size:11px}}\n/* A badge wider than «×99» would cover the art: the art goes under it. */\n.dialog .inv-cell[data-wide-qty]{padding-top:22px}\n.inv-cell[aria-pressed=\"true\"] .inv-name{color:var(--mp-text)}\n.inv-cell[data-empty] .inv-name,.inv-cell[data-empty] .inv-qty{color:var(--mp-text-3)}\n.inv-qty{position:absolute;top:4px;right:4px;max-width:calc(100% - 8px);box-sizing:border-box;height:18px;padding:0 5px;\n border-radius:6px;background:var(--mp-window-background);font-weight:700;font-size:12px;line-height:18px;white-space:nowrap}\n.inv-new{position:absolute;top:6px;left:6px;width:8px;height:8px;border-radius:4px;background:var(--mp-mint)}\n.inv-side{flex:1 0 auto;display:flex;flex-direction:column;gap:16px}\n.inv-side .window-actions{margin-top:auto}\n.dialog .inv-side .window-actions button{gap:8px}\n.inv-side .window-actions svg{flex:none}\n\n.inv-side .window-actions [data-part=icon]{flex:none}\n.inv-detail{border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line);padding:16px;\n display:flex;flex-direction:column;gap:12px}\n.inv-detail-head{display:flex;align-items:center;gap:16px}\n.inv-detail-art{width:72px;height:72px;flex:none;box-sizing:border-box;border-radius:12px;background:var(--mp-raised);\n border:1px solid var(--mp-line-strong);display:flex;align-items:center;justify-content:center}\n.inv-detail-art img{width:56px;height:56px;object-fit:contain}\n.inv-detail-meta{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}\n.inv-detail-meta h3{margin:0;font-size:18px;font-weight:600;line-height:1.3;overflow-wrap:break-word}\n.inv-rarity{align-self:flex-start;max-width:100%;min-height:24px;padding:1px 8px;border-radius:8px;border:1px solid var(--mp-gold);\n color:var(--mp-gold);font-weight:600;font-size:13px;line-height:20px;box-sizing:border-box;overflow-wrap:anywhere}\n.inv-have{font-weight:600;font-size:13px;line-height:1.4;color:var(--mp-text-3)}\n.inv-have b{color:var(--mp-text);font-weight:700}\n.inv-desc{margin:0;color:var(--mp-text-2);font-size:15px;line-height:1.45}\n.inv-empty{margin:0;color:var(--mp-text-3);text-align:center;padding:24px 0}\n.inv-grid:empty{display:none}\n.dialog:has(.chest-list),.dialog:has(.chest-rewards){gap:12px}\n.chest-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px;container-type:inline-size}\n.chest-row{display:flex;align-items:center;gap:12px;padding:12px;box-sizing:border-box;\n border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line)}\n.chest-row>.chest-art{flex:none;width:48px;height:48px}.chest-row[data-status=\"cooldown\"]>.chest-art{opacity:.55}\n.chest-meta{flex:1;display:flex;flex-direction:column;min-width:0}\n/* Titles wrap by words as MPS_P_D_Chests («Сундук / приключений»); only a word of 14+ letters that\n does not fit a line is hyphenated, never a short one. */\n.chest-meta strong{font-size:15px;font-weight:600;line-height:1.25;overflow-wrap:break-word;hyphens:auto;\n hyphenate-limit-chars:14 6 5}\n.chest-meta small{font-size:13px;font-weight:600;line-height:1.4;color:var(--mp-text-3)}\n.dialog .chest-action{flex:none;width:104px;height:48px;min-height:48px;padding:0 8px;box-sizing:border-box;\n border-radius:12px;display:flex;align-items:center;justify-content:center;gap:6px;font-size:15px;font-weight:600;\n white-space:nowrap}\n/* Narrower than the 310px rows of the board (a 360px phone): smaller art and gaps, 14px titles, so a\n word such as «приключений» still fits one line. */\n@container (max-width:300px){\n .chest-row{gap:8px;padding:10px}.chest-row>.chest-art{width:40px;height:40px}.chest-meta strong{font-size:14px}\n}\n.dialog .chest-wait{border:1px solid var(--mp-line);color:var(--mp-text-3);font-size:13px}\n.dialog button.chest-action[data-variant=\"ghost\"]{border-color:var(--mp-line-strong);color:var(--mp-text);font-weight:700}\n.chest-action img{width:20px;height:20px;object-fit:contain}.chest-action>svg{flex:none}\n.chest-action>[data-part=icon]{flex:none}\n.chest-art .chest-lid{fill:var(--mp-chest-bronze)}.chest-art .chest-body{fill:var(--mp-chest-bronze-deep)}\n.chest-art .chest-band,.chest-art .chest-lock{fill:var(--mp-gold)}\n.chest-art .chest-lock{stroke:var(--mp-window-background)}\n.chest-art .chest-rim{fill:var(--mp-chest-bronze-rim)}.chest-art .chest-inside{fill:var(--mp-window-background)}\n.chest-art .chest-coin{fill:var(--mp-gold);stroke:var(--mp-window-background)}\n.chest-art .chest-gem{fill:var(--mp-violet);stroke:var(--mp-window-background)}\n.chest-art[data-tone=\"green\"] .chest-lid{fill:var(--mp-mint)}.chest-art[data-tone=\"green\"] .chest-body{fill:var(--mp-chest-green-deep)}\n.chest-art[data-tone=\"violet\"] .chest-lid{fill:var(--mp-violet)}.chest-art[data-tone=\"violet\"] .chest-body{fill:var(--mp-chest-violet-deep)}\n.chest-art[data-tone=\"green\"] .chest-rim{fill:var(--mp-chest-green-deep)}\n.chest-art[data-tone=\"violet\"] .chest-rim{fill:var(--mp-chest-violet-deep)}\n.chest-opened{display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center}\n.chest-opened p{margin:0;color:var(--mp-text-2);font-size:15px;line-height:1.45}\n.chest-rewards{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}\n.chest-reward{height:64px;box-sizing:border-box;display:flex;flex-direction:column;align-items:center;justify-content:center;\n gap:4px;min-width:0;border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line)}\n.chest-reward img{width:28px;height:28px;object-fit:contain}\n.chest-reward strong{font-size:15px;font-weight:700;line-height:1.2}.chest-reward[data-gold] strong{color:var(--mp-gold)}\n.skin-page{position:fixed;inset:0;z-index:20;box-sizing:border-box;overflow:auto;padding:16px;display:flex;\n flex-direction:column;gap:16px;background:var(--mp-window-background);color:var(--mp-text)}\n.skin-head{display:flex;align-items:center;gap:12px;min-height:40px}\n.skin-head h3{flex:1;margin:0;font-size:22px;line-height:1.3}\n.skin-page button.skin-back{width:40px;height:40px;min-height:40px;padding:0;border-radius:8px;border:1px solid var(--mp-line);\n background:var(--mp-navy);color:var(--mp-text-2)}\n.skin-rarity{height:24px;padding:0 8px;border-radius:8px;background:var(--mp-violet);color:var(--mp-on-accent);\n font-weight:700;font-size:12px;line-height:24px;text-transform:uppercase}\n.skin-index{font-weight:700;font-size:13px;color:var(--mp-text-2)}\n.skin-stage{display:flex;flex-direction:column;gap:16px}\n.skin-preview-card{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px 8px;padding:24px 16px;\n border-radius:16px;background:var(--mp-navy);border:1px solid var(--mp-line)}\n.skin-page button.skin-nav{width:44px;height:44px;min-height:44px;padding:0;border-radius:12px;background:var(--mp-surface);\n border:1px solid var(--mp-line);color:var(--mp-text-2)}\n.skin-preview{width:188px;height:188px;max-width:100%;justify-self:center;box-sizing:border-box;border-radius:16px;\n background:var(--mp-surface);border:1px dashed var(--mp-line-strong);display:flex;align-items:center;justify-content:center;overflow:hidden}\n.skin-preview img{width:100%;height:100%;object-fit:contain}\n.skin-name{grid-column:1/4;margin:0;text-align:center;font-size:30px;line-height:1.2;font-weight:700}\n.skin-perk{grid-column:1/4;justify-self:center;display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:var(--mp-text-2)}\n.skin-side{display:flex;flex-direction:column;gap:16px;min-height:0}\n.skin-variants{display:flex;justify-content:center;gap:12px}\n.skin-page button.skin-variant{width:48px;height:48px;min-height:48px;padding:0;border-radius:12px;background:var(--mp-surface);\n border:1px solid var(--mp-line);display:flex;align-items:center;justify-content:center;color:var(--mp-text-3)}\n.skin-page button.skin-variant[aria-pressed=\"true\"]{background:var(--mp-raised);border:2px solid var(--mp-violet)}\n.skin-page button.skin-variant[data-state=\"locked\"]{background:var(--mp-night)}\n.skin-page button.skin-variant[data-state=\"unknown\"]{background:var(--mp-night);border-style:dashed;font-weight:700}\n.skin-page button.skin-variant:disabled{opacity:1}\n.skin-dot{width:24px;height:24px;border-radius:12px;background:var(--mp-violet)}\n.skin-variant[data-tone=\"mint\"] .skin-dot{background:var(--mp-mint)}\n.skin-variant[data-tone=\"violet-soft\"] .skin-dot{background:var(--mp-violet-text)}\n.skin-variant img{width:24px;height:24px;object-fit:contain}\n.skin-unlock{display:flex;flex-direction:column;gap:12px;padding:16px;border-radius:16px;background:var(--mp-navy);\n border:1px solid var(--mp-line)}\n.skin-ad{display:flex;flex-direction:column;gap:8px}\n.skin-ad-line{display:flex;justify-content:space-between;font-size:13px;font-weight:600;color:var(--mp-text-2)}\n.skin-ad-line b{color:var(--mp-text);font-weight:700}\n.skin-bar{height:8px;border-radius:4px;background:var(--mp-night);overflow:hidden}\n.skin-bar>svg{display:block;width:100%;height:100%;fill:var(--mp-points)}\n\n.skin-bar>[data-part=icon]{display:block;width:100%;height:100%;fill:var(--mp-points)}\n.skin-actions{display:flex;flex-direction:column;gap:8px}\n.skin-page button.skin-watch,.skin-page button.skin-buy{height:48px;gap:8px;font-weight:600}\n.skin-short{display:none}\n.skin-price{display:inline-flex;align-items:center;gap:6px;color:var(--mp-points);font-weight:700}\n@media (orientation:landscape) and (max-height:520px){\n .dialog:has(.inv-grid){width:min(694px,100%);max-height:100%;display:grid;container-type:inline-size;\n  grid-template-columns:auto auto minmax(0,1fr) auto;grid-template-rows:auto minmax(0,1fr);gap:12px;padding:16px;align-items:start}\n .dialog:has(.inv-grid)>.dialog-head{display:contents}\n .dialog:has(.inv-grid) .dialog-head h3{grid-column:1;grid-row:1;align-self:center;padding:0}\n .dialog:has(.inv-grid) .dialog-close{grid-column:4;grid-row:1;align-self:center;margin:0}\n .inv-tabs{grid-column:2;grid-row:1;display:flex;margin-left:8px}\n .dialog .inv-tabs button{font-size:14px}\n .inv-count{height:18px;min-width:18px;padding:0 5px;border-radius:9px;line-height:18px}\n .inv-grid{grid-column:1/3;grid-row:2;width:min(380px,100cqw - 228px);height:100%;\n  grid-auto-rows:max(64px,calc((100% - 8px) / 2))}\n .inv-side{grid-column:3/5;grid-row:2;height:100%;margin-left:4px;gap:8px;min-height:0}\n /* Details longer than the panel scroll; the shadow at the cut edge shows there is more (the\n  covers scroll with the text, the shadows stay: no shadow when everything fits). */\n .inv-side .inv-detail{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;\n  scrollbar-color:var(--mp-line-strong) transparent;\n  background:linear-gradient(var(--mp-surface) 30%,transparent) center top/100% 28px no-repeat local,\n   linear-gradient(transparent,var(--mp-surface) 70%) center bottom/100% 28px no-repeat local,\n   radial-gradient(farthest-side at 50% 0,var(--mp-window-background),transparent) center top/100% 12px no-repeat scroll,\n   radial-gradient(farthest-side at 50% 100%,var(--mp-window-background),transparent) center bottom/100% 12px no-repeat scroll,\n   var(--mp-surface)}\n .inv-side{container-type:inline-size}\n}\n@container (max-width:230px){\n /* Below the 694px board the selected cell already shows the art: the details give its width and\n  height to the name, rarity and description, so they fit the panel of a 640–667px phone. */\n .inv-side .inv-detail-art{display:none}\n .inv-side .inv-detail-meta h3{font-size:16px}.inv-side .inv-desc{font-size:13px}\n /* A narrow side keeps one row of actions: «Обменять» becomes the 48px icon button of B_Collection. */\n .inv-side .window-actions{flex-wrap:nowrap}\n .inv-side .window-actions>*{flex:1 1 auto;min-width:0}\n .dialog .inv-side .window-actions>button.inv-exchange:not(:only-child){flex:none;width:48px;padding:0}\n .inv-side .window-actions>.inv-exchange:not(:only-child)>.inv-exchange-label{display:none}\n}\n@media (orientation:landscape) and (max-height:520px){\n .inv-side:has(.inv-empty){grid-column:1/5}\n .inv-detail{padding:8px 14px;gap:8px}.inv-detail-head{gap:12px}\n .inv-detail-art{width:64px;height:64px}.inv-detail-meta h3{line-height:1.25}\n .inv-rarity{min-height:22px;font-size:12px;line-height:18px}.inv-have{font-size:12px;line-height:1.3}\n .inv-desc{font-size:14px;line-height:1.4}\n .inv-side .window-actions{flex-direction:row;flex-wrap:wrap;margin-top:0}\n .inv-side .window-actions>*{flex:1 0 auto;width:auto;padding:0 12px;white-space:nowrap}\n .dialog:has(.chest-list){width:min(412px,100%);gap:8px;padding:20px}\n .dialog:has(.chest-list)>.dialog-head{margin-bottom:4px}\n .chest-row{padding:8px 8px 8px 12px}.chest-row>.chest-art{width:40px;height:40px}.dialog .chest-action{width:120px}\n .dialog:has(.chest-rewards){width:min(300px,100%);gap:8px;padding:20px}\n .chest-opened{flex-direction:row;text-align:left}\n .chest-reward{height:72px}.chest-reward img{width:32px;height:32px}\n .dialog:has(.chest-rewards) .window-actions{margin-top:4px}\n .skin-stage{display:grid;grid-template-columns:1fr 1fr;gap:16px;flex:1;min-height:0}\n .skin-preview-card{padding:16px}.skin-preview{width:160px;height:160px}.skin-name{font-size:22px}\n .skin-unlock{display:contents}\n .skin-ad{padding:12px 16px;border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line)}\n .skin-long{display:none}.skin-short{display:inline}\n .skin-actions{flex-direction:row;margin-top:auto}.skin-actions>*{flex:1}\n}\n.chest-empty{display:flex;flex-direction:column;align-items:center;gap:12px;padding:24px 8px;text-align:center;color:var(--mp-text-2)}";
